// 유리 구슬 지구본(displayMode==='photo') 뒤에 깔리는 실사 우주 배경.
// 원본: Westerlund 2 성단 — 허블 25주년 'Celestial Fireworks'
//       (NASA, ESA, Hubble Heritage Team STScI/AURA · public domain / CC BY 4.0)
// 가공: 성단 위주 크롭 → 1080x2340 → 앱 보라 톤 그레이딩 → JPEG q6.
//
// WebView가 source={{ html }}로만 뜨고 baseUrl이 없어 assets/ 파일을 경로로 참조할 수 없다.
// → data URI로 globeHTML에 인라인한다 (WORLD_GEO_INLINE·THREE_INLINE과 같은 방식).
// 크레딧은 SettingsScreen 하단에 표기 중 — 이미지를 바꿀 때 함께 갱신할 것.
export const GLASS_SPACE_BG =
  'data:image/jpeg;base64,';
